// Pixel-art sprite set (generated by scripts/pixel/build.py, rules in scripts/pixel/reference/STYLE.md).
// Sprites are drawn at native size and must be displayed at 1x / integer scales with
// `image-rendering: pixelated`.
export const PIXEL_ICON_DIR = '/pixel/icons';

export const PIXEL_ICON_SIZES = {
	// resources
	gold: [40, 40],
	wood: [40, 40],
	stone: [40, 40],
	coal: [40, 40],
	food: [40, 40],
	meat: [40, 40],
	// menu buttons + badges
	menu_character: [40, 40],
	menu_merchant: [40, 40],
	menu_farm: [40, 40],
	level_star: [24, 24],
	xp: [40, 40],
	cash_bag: [24, 24],
	unknown: [12, 16],
	// portraits
	hero: [40, 56],
	merchant: [40, 56],
	// equipment slots
	equip_head: [40, 40],
	equip_neck: [40, 40],
	equip_chest: [40, 40],
	equip_mainHand: [40, 40],
	equip_offHand: [40, 40],
	equip_legs: [40, 40],
	equip_feet: [40, 40],
	equip_ring: [40, 40],
	// castle by upgrade level (grows each level; 6 is the animated max)
	castle_1: [32, 32],
	castle_2: [32, 32],
	castle_3: [40, 40],
	castle_4: [48, 48],
	castle_5: [56, 56],
	castle_6: [72, 72],
	// map: one icon per biome
	biome_forest: [32, 32],
	biome_plains: [32, 32],
	biome_hills: [32, 32],
	biome_swamp: [32, 32],
	biome_tundra: [32, 32],
	biome_lake: [32, 32],
	biome_grounds: [32, 32],
	// farm animals
	animal_chicken: [40, 40],
	animal_pig: [40, 40],
	animal_cow: [40, 40],
	animal_deer: [40, 40],
} as const;

export type PixelIconName = keyof typeof PIXEL_ICON_SIZES;

export const pixelIconSrc = (name: PixelIconName) => `${PIXEL_ICON_DIR}/${name}.png`;

// Resource key -> sprite. Resources without an entry (e.g. xp) fall back to their emoji.
export const RESOURCE_PIXEL_ICONS: Partial<Record<string, PixelIconName>> = {
	gold: 'gold',
	wood: 'wood',
	stone: 'stone',
	coal: 'coal',
	food: 'food',
	meat: 'meat',
	xp: 'xp',
};

// Equipment slot -> its pixel icon (both ring slots share one sprite)
export const EQUIPMENT_PIXEL_ICONS: Record<string, PixelIconName> = {
	head: 'equip_head',
	neck: 'equip_neck',
	chest: 'equip_chest',
	mainHand: 'equip_mainHand',
	offHand: 'equip_offHand',
	legs: 'equip_legs',
	feet: 'equip_feet',
	ring1: 'equip_ring',
	ring2: 'equip_ring',
};

// Farm animal id -> sprite
export const ANIMAL_PIXEL_ICONS: Record<string, PixelIconName> = {
	chicken: 'animal_chicken',
	pig: 'animal_pig',
	cow: 'animal_cow',
	deer: 'animal_deer',
};

// Biome -> map icon (the 'empty' biome has none; the castle uses castle_<level>)
export const BIOME_PIXEL_ICONS: Record<string, PixelIconName | undefined> = {
	forest: 'biome_forest',
	plains: 'biome_plains',
	hills: 'biome_hills',
	swamp: 'biome_swamp',
	tundra: 'biome_tundra',
	lake: 'biome_lake',
	grounds: 'biome_grounds',
};

export const castleIconName = (level: number): PixelIconName =>
	`castle_${Math.max(1, Math.min(6, Math.floor(level)))}` as PixelIconName;
